+        BigDecimal term = BigDecimal.ONE;
+        BigDecimal sum = BigDecimal.ONE;
+        final BigDecimal exponent = this.delegate;
+
+        int i = 1;
+        while (term.signum() != 0) {
+            term = term.multiply(exponent, this.mathContext).divide(BigDecimal.valueOf(i), this.mathContext);
